sys_script_include.script:
var TBABuddyAvailabilityAjax = Class.create();
TBABuddyAvailabilityAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    isBuddyAvailable: function() {
        var buddyId = this.getParameter('sysparm_buddy');
        var startTime = this.getParameter('sysparm_start');
        var endTime = this.getParameter('sysparm_end');

        if (!buddyId || !startTime || !endTime) {
            return 'true';
        }

        var schedGr = new GlideRecord('cmn_schedule');
        schedGr.addQuery('x_travel_buddy_app_u_buddy_profile', buddyId);
        schedGr.query();

        while (schedGr.next()) {
            var conflict = new GlideRecord('cmn_schedule_span');
            conflict.addQuery('schedule', schedGr.getUniqueValue());
            conflict.addQuery('type', 'Booked');
            conflict.addQuery('u_start_date_time', '<=', endTime);
            conflict.addQuery('u_end_date_time', '>=', startTime);
            conflict.addNotNullQuery('u_start_date_time');
            conflict.addNotNullQuery('u_end_date_time');
            conflict.query();
            if (conflict.hasNext()) {
                return 'false';
            }
        }

        return 'true';
    },

    type: 'TBABuddyAvailabilityAjax'
});
